import zipfile, re, shutil

NS = '{http://schemas.openxmlformats.org/spreadsheetml/2006/main}'

def col_letter(ref):
    return re.match(r'[A-Z]+', ref).group(0)

def col_index(letter):
    i = 0
    for ch in letter:
        i = i * 26 + (ord(ch) - 64)
    return i

def cell_ref(row, col):
    return f"{col}{row}"

def parse_ref(ref):
    m = re.match(r'([A-Z]+)(\d+)', ref)
    return m.group(1), int(m.group(2))

SRC = 'sales_data.xlsx'
TMP = 'sales_data_val.xlsx'

with zipfile.ZipFile(SRC) as z:
    names = z.namelist()
    data = {n: z.read(n) for n in names}

import xml.etree.ElementTree as ET
root = ET.fromstring(data['xl/worksheets/sheet1.xml'])

sheet_data = root.find(f'{NS}sheetData')
cells = {}
for row in sheet_data.findall(f'{NS}row'):
    rnum = int(row.get('r'))
    for c in row.findall(f'{NS}c'):
        ref = c.get('r')
        letter, r = parse_ref(ref)
        t = c.get('t')
        v_el = c.find(f'{NS}v')
        f_el = c.find(f'{NS}f')
        val = None
        if v_el is not None and v_el.text not in (None, ''):
            if t == 'inlineStr':
                is_el = c.find(f'{NS}is/{NS}t')
                val = is_el.text if is_el is not None else None
            else:
                val = float(v_el.text)
        cells[(r, letter)] = val

def get(ref):
    letter, r = parse_ref(ref)
    return cells.get((r, letter))

def eval_formula(f):
    f = f.strip()
    m = re.fullmatch(r'([A-Z]+\d+)\*([A-Z]+\d+)', f)
    if m:
        return get(m.group(1)) * get(m.group(2))
    m = re.fullmatch(r'([A-Z]+\d+)-([A-Z]+\d+)\*([A-Z]+\d+)', f)
    if m:
        return get(m.group(1)) - get(m.group(2)) * get(m.group(3))
    m = re.fullmatch(r'([A-Z]+\d+)/([A-Z]+\d+)', f)
    if m:
        return get(m.group(1)) / get(m.group(2))
    m = re.fullmatch(r'SUM\(([A-Z]+)(\d+):\1(\d+)\)', f)
    if m:
        letter, r1, r2 = m.group(1), int(m.group(2)), int(m.group(3))
        return sum(get(cell_ref(r, letter)) for r in range(r1, r2 + 1))
    raise ValueError(f"unhandled formula: {f}")

updated = 0
for row in sheet_data.findall(f'{NS}row'):
    for c in row.findall(f'{NS}c'):
        f_el = c.find(f'{NS}f')
        v_el = c.find(f'{NS}v')
        if f_el is not None:
            val = eval_formula(f_el.text)
            if v_el is None:
                v_el = ET.SubElement(c, f'{NS}v')
            v_el.text = repr(val)
            updated += 1

data['xl/worksheets/sheet1.xml'] = ET.tostring(root, xml_declaration=True, encoding='UTF-8')

with zipfile.ZipFile(TMP, 'w', zipfile.ZIP_DEFLATED) as z:
    for n in names:
        z.writestr(n, data[n])

shutil.move(TMP, SRC)
print(f"updated {updated} formula cached values")

